/* One Trails round, played inside the tournament page (cup/page.html): a Trails Tournament runs on it the way the Odd One Out one runs on
 * cup/play.js (window.CupPlay), with the same contract, so the page can take either.
 *
 * The same game as game-pages/trails.html: the seeded boards are copied from it verbatim (the block between the seeded-boards markers), and so
 * are its rules and scoring (trails.html, "What a trail pays" and "---------- play ----------"): start on 1, step to a neighbouring cell (a
 * straight drag covers several), never through a wall, never onto a number out of turn, never past the last number before every cell is
 * covered; dragging back over the trail rewinds it. A trail pays its level's base, 40 + 10 × level, doubled when it is drawn within its par
 * (PAR, seconds), the bonus fading to nothing at twice the par. A hint (back to where the trail left the way, then the next few squares) costs
 * 10 seconds off the round's clock, and the same 10 seconds count against that trail's time. Trail g of a round is level g+1 (twenty levels,
 * then the 7×7 ones at random), so both players of a match, given one seed, get the same trails in the same order. Higher score wins.
 *
 *   const h = CupTrails.start({
 *     mount,                 // element (or selector) the round fills; best a full-screen fixed box
 *     boardSeed,             // the match's seed (whole number)
 *     startAt,               // server time the round starts (ms or ISO); nothing can be drawn before it
 *     serverNow,             // server time when the response carrying startAt was made (ms or ISO)
 *     receivedAt,            // optional: Date.now() when that response arrived (default: now)
 *     clockOffset,           // optional: server minus client clock in ms; wins over serverNow/receivedAt
 *     roundSec = 45,
 *     me: { name, photoUrl? }, opponent: { name, photoUrl? } | null,   // a face in the round frame; initials when there's no photo or it fails
 *     getOpponentLive: () => number | null,   // polled 4× a second; the host keeps it fresh from /state
 *     onLive(score, progress), // on a change, at most 4× a second; progress = { board }: the trail the player is on now (trail N of the seed,
 *                            // 0-based; it moves on the moment a trail is finished). Viewers draw it with drawBoard.
 *     onFinal(score),        // exactly once, when the round is over (also after the app comes back from the background)
 *     onStart(),             // optional: the first trail just appeared
 *     onProgress(p),         // optional: after every trail and hint, { score, gi, solved, quick, hints } — the host keeps it to resume
 *     resume,                // optional: that object, after a reload mid-round: the round carries on from it (trail gi, drawn afresh)
 *     sound = true,
 *   });
 *   h.stop();  h.score();  h.state();   // 'wait' | 'play' | 'closing' | 'over' | 'stopped'
 *   CupTrails.unlockAudio()   // call inside the tap that joins the match, so iOS lets the countdown beep
 *   CupTrails.boardHtml(seed, n, { size, color, key, ok })   // trail n of a seed, empty and read-only, as HTML (ok: true flashes it green)
 *   CupTrails.drawBoard(mount, seed, n, opts)                // the same, put into mount
 *   CupTrails.boardAt(seed, n)                               // the trail itself: { n, level, dots, walls, path }
 *
 * Input is touch (touchstart/touchmove on the board, taken at once, no scroll or zoom), pointer events for a mouse (or for touch where there
 * are no touch events), arrow keys and Backspace on the focused board. A move keeps the moment the finger made it: after the buzzer only a
 * move made before it counts (the round waits a moment for one that reaches the page late). No network, no dependencies. */
